## Tests for: parseAge (src/age.js)

**Interrogation notes (read before writing):**

`parseInt(s, 10)` returns `NaN` for any input it cannot parse (non-numeric strings, `null`→`"null"`, `undefined`→`"undefined"`, objects, arrays, booleans, `""`, whitespace-only, `"Infinity"`, `"NaN"`). The range check is:

```js
if (n < 0 || n > 150) throw new RangeError(...)
```

`NaN < 0` is `false` and `NaN > 150` is `false` — **both branches of the guard are false for `NaN`**, so the function falls through and `return n` returns `NaN` instead of throwing. This directly contradicts the stated contract ("throws RangeError for anything else"). Every non-numeric input is silently accepted and returns `NaN` as if it were a valid age.

Separately, `parseInt` parses only a *leading* numeric prefix and ignores trailing garbage (`"150abc"` → `150`), so malformed strings that happen to start with digits in range are accepted rather than rejected.

**Scenarios covered:**
- [x] Happy path: valid numeric strings in range
- [x] Boundary: 0, 150 (valid), -1, 151 (invalid), decimal truncation
- [x] Error: null, undefined, non-numeric string, empty string, whitespace, object, array, boolean, `"NaN"`, `"Infinity"`, trailing-garbage string
- [x] Oversized: very long numeric string exceeding range
- [x] Malformed/injection-shaped input
- [x] Idempotency: same input called twice

```js
// src/age.test.js
import { test, describe } from 'node:test'
import assert from 'node:assert/strict'
import { parseAge } from './age.js'

describe('parseAge', () => {
  describe('happy path', () => {
    test('should return 25 when input is "25"', () => {
      const result = parseAge('25')
      assert.equal(result, 25)
    })

    test('should return integer type for valid numeric string', () => {
      const result = parseAge('30')
      assert.equal(Number.isInteger(result), true)
    })
  })

  describe('boundary conditions', () => {
    test('should return 0 when input is the minimum valid age "0"', () => {
      const result = parseAge('0')
      assert.equal(result, 0)
    })

    test('should return 150 when input is the maximum valid age "150"', () => {
      const result = parseAge('150')
      assert.equal(result, 150)
    })

    test('should throw RangeError when input is "-1" (just below min)', () => {
      assert.throws(() => parseAge('-1'), RangeError)
    })

    test('should throw RangeError when input is "151" (just above max)', () => {
      assert.throws(() => parseAge('151'), RangeError)
    })

    test('should truncate decimal string "45.9" to integer 45 (documents current parseInt truncation behavior)', () => {
      const result = parseAge('45.9')
      assert.equal(result, 45)
    })
  })

  describe('invalid input — expected to throw per contract', () => {
    // NOTE: each test below asserts the documented contract
    // ("throws RangeError for anything else"). Several currently
    // FAIL because NaN comparisons short-circuit the range guard —
    // see Handoffs. These assertions are intentionally left as the
    // correct expected behavior, not weakened to match the bug.

    test('should throw RangeError when input is a non-numeric string "abc"', () => {
      assert.throws(() => parseAge('abc'), RangeError)
    })

    test('should throw RangeError when input is null', () => {
      assert.throws(() => parseAge(null), RangeError)
    })

    test('should throw RangeError when input is undefined', () => {
      assert.throws(() => parseAge(undefined), RangeError)
    })

    test('should throw RangeError when input is an empty string', () => {
      assert.throws(() => parseAge(''), RangeError)
    })

    test('should throw RangeError when input is a whitespace-only string', () => {
      assert.throws(() => parseAge('   '), RangeError)
    })

    test('should throw RangeError when input is a plain object', () => {
      assert.throws(() => parseAge({}), RangeError)
    })

    test('should throw RangeError when input is an array', () => {
      assert.throws(() => parseAge([]), RangeError)
    })

    test('should throw RangeError when input is a boolean', () => {
      assert.throws(() => parseAge(true), RangeError)
    })

    test('should throw RangeError when input is the literal string "NaN"', () => {
      assert.throws(() => parseAge('NaN'), RangeError)
    })

    test('should throw RangeError when input is the string "Infinity"', () => {
      assert.throws(() => parseAge('Infinity'), RangeError)
    })

    test('should throw RangeError when input has trailing non-numeric characters ("150abc")', () => {
      assert.throws(() => parseAge('150abc'), RangeError)
    })

    test('should throw RangeError when input looks like an injection payload ("1; DROP TABLE users;")', () => {
      assert.throws(() => parseAge('1; DROP TABLE users;'), RangeError)
    })
  })

  describe('oversized input', () => {
    test('should throw RangeError when input is an extremely large numeric string', () => {
      const huge = '9'.repeat(1000)
      assert.throws(() => parseAge(huge), RangeError)
    })
  })

  describe('idempotency', () => {
    test('should return the same result when called twice with the same input', () => {
      const first = parseAge('42')
      const second = parseAge('42')
      assert.equal(first, second)
    })
  })
})
```

**Coverage added:** happy path branch (valid range), both throw branches (`n < 0`, `n > 150`), and — critically — the unguarded fall-through branch for `NaN`-producing input, which the original suite had no coverage for at all.

