## Tests for: `isAdult` (src/age.js)

**Source read:**
```js
export function isAdult(age) {
  return age > 18
}
```
Spec: *"a person aged 18 or over is an adult"* → correct contract is `age >= 18`. The source uses `age > 18`, which excludes exactly 18. That is a boundary bug, not a test-writing problem — it is **not fixed here**.

**Scenarios covered:**
- [ ] Happy path: clearly adult age (25) → true
- [ ] Boundary: 18 (exactly the threshold — spec says adult) → **exposes the bug**
- [ ] Boundary: 17, 19, 0, -1
- [ ] Boundary: decimals straddling 18 (17.999, 18.0, 18.0001)
- [ ] Boundary: huge/extreme numbers (MAX_SAFE_INTEGER, Infinity, -Infinity)
- [ ] Invalid type: null, undefined, NaN, non-numeric string, numeric string, boolean, object, array
- [ ] Determinism: same call twice yields same result (pure function sanity check)

```js
// test/age.test.js
import { test, describe } from 'node:test'
import assert from 'node:assert/strict'
import { isAdult } from '../src/age.js'

describe('isAdult', () => {
  describe('happy path', () => {
    test('should return true when age is well above 18', () => {
      // Arrange
      const age = 25
      // Act
      const result = isAdult(age)
      // Assert
      assert.equal(result, true)
    })

    test('should return false when age is well below 18', () => {
      // Arrange
      const age = 5
      // Act
      const result = isAdult(age)
      // Assert
      assert.equal(result, false)
    })
  })

  describe('boundary conditions', () => {
    test('should return true when age is exactly 18 (spec: "18 or over is an adult")', () => {
      // Arrange
      const age = 18
      // Act
      const result = isAdult(age)
      // Assert — this is the contract, not the current implementation's behavior
      assert.equal(result, true, 'age 18 must be classified as adult per spec')
    })

    test('should return false when age is 17 (one below threshold)', () => {
      const age = 17
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should return true when age is 19 (one above threshold)', () => {
      const age = 19
      const result = isAdult(age)
      assert.equal(result, true)
    })

    test('should return false when age is 0', () => {
      const age = 0
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should return false when age is negative (-1)', () => {
      const age = -1
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should return false when age is a fraction just under 18 (17.999)', () => {
      const age = 17.999
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should return true when age is exactly 18.0 (float form of threshold)', () => {
      const age = 18.0
      const result = isAdult(age)
      assert.equal(result, true, 'age 18.0 must be classified as adult per spec')
    })

    test('should return true when age is a fraction just over 18 (18.0001)', () => {
      const age = 18.0001
      const result = isAdult(age)
      assert.equal(result, true)
    })

    test('should return true when age is Number.MAX_SAFE_INTEGER', () => {
      const age = Number.MAX_SAFE_INTEGER
      const result = isAdult(age)
      assert.equal(result, true)
    })

    test('should return true when age is Infinity', () => {
      const age = Infinity
      const result = isAdult(age)
      assert.equal(result, true)
    })

    test('should return false when age is -Infinity', () => {
      const age = -Infinity
      const result = isAdult(age)
      assert.equal(result, false)
    })
  })

  describe('invalid / adversarial input', () => {
    test('should not throw and should return false when age is null', () => {
      const age = null
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should not throw and should return false when age is undefined', () => {
      const age = undefined
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should not throw and should return false when age is NaN', () => {
      const age = NaN
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should not throw and should return false when age is a non-numeric string', () => {
      const age = 'eighteen'
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should coerce numeric strings when age is "18" (string form of threshold)', () => {
      const age = '18'
      const result = isAdult(age)
      // Per spec, "18" represents the adult threshold and should resolve to true.
      assert.equal(result, true, 'string "18" must be classified as adult per spec')
    })

    test('should not throw and should return false when age is a boolean (true)', () => {
      const age = true
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should not throw and should return false when age is a boolean (false)', () => {
      const age = false
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should not throw and should return false when age is a plain object', () => {
      const age = {}
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should not throw when age is an array', () => {
      const age = [20]
      const result = isAdult(age)
      assert.equal(result, true)
    })
  })

  describe('determinism', () => {
    test('should return the same result when called twice with the same input', () => {
      const age = 18
      const first = isAdult(age)
      const second = isAdult(age)
      assert.equal(first, second)
    })
  })
})
```

